package com.netflix.frigga.ami;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class AppVersionTest {

    @Test
    public void parseNameCorrectNameTest() {
        String correctName = "MyApp-1.0.0-h2.12345678";
        AppVersion appVersion = AppVersion.parseName(correctName);
        assertEquals("MyApp", appVersion.getPackageName());
        assertEquals("1.0.0", appVersion.getVersion());
        assertEquals("h2", appVersion.getBuildJobName());
        assertEquals("12345678", appVersion.getBuildNumber());
    }

    @Test
    public void parseNameIncorrectNameTest() {
        String incorrectName = "MyApp-1.0.0";
        AppVersion appVersion = AppVersion.parseName(incorrectName);
        assertEquals("", appVersion.getPackageName());
        assertEquals("", appVersion.getVersion());
        assertEquals("", appVersion.getBuildJobName());
        assertEquals("", appVersion.getBuildNumber());
    }

    @Test
    public void compareToGreaterTest() {
        AppVersion appVersion1 = AppVersion.parseName("MyApp-1.0.0-h2.1234");
        AppVersion appVersion2 = AppVersion.parseName("MyApp-0.9.9-h2.1233");
        assertTrue(appVersion1.compareTo(appVersion2) > 0);
    }

    @Test
    public void compareToEqualTest() {
        AppVersion appVersion1 = AppVersion.parseName("MyApp-1.0.0-h1.1234");
        AppVersion appVersion2 = AppVersion.parseName("MyApp-1.0.0-h1.1234");
        assertEquals(0, appVersion1.compareTo(appVersion2));
    }

    @Test
    public void getAppVersionPatternTest() {
        String validPatternString = AppVersion.getAppVersionPattern().toString();
        assertTrue(validPatternString.contains("v"));
        assertTrue(validPatternString.contains("b"));
    }

    @Test
    public void toStringTest() {
        AppVersion appVersion = AppVersion.parseName("MyApp-1.0.0-h2.1234");
        assertEquals("MyApp-1.0.0-h2.1234", appVersion.toString());
    }

    @Test
    public void hashCodeTest() {
        AppVersion appVersion1 = AppVersion.parseName("MyApp-1.0.0-h1.1234");
        AppVersion appVersion2 = AppVersion.parseName("MyApp-1.0.0-h1.1234");
        AppVersion appVersion3 = AppVersion.parseName("MyApp-1.0.0-h2.1234");
        assertEquals(appVersion1.hashCode(), appVersion2.hashCode());
        assertNotEquals(appVersion1.hashCode(), appVersion3.hashCode());
    }

    @Test
    public void equalsTest() {
        AppVersion appVersion1 = AppVersion.parseName("MyApp-1.0.0-h1.1234");
        AppVersion appVersion2 = AppVersion.parseName("MyApp-1.0.0-h1.1234");
        AppVersion appVersion3 = AppVersion.parseName("MyApp-1.0.0-h2.1234");
        assertTrue(appVersion1.equals(appVersion2));
        assertFalse(appVersion1.equals(appVersion3));
    }
}
